"use client"

import React from "react"
import * as AccordionPrimitive from "@radix-ui/react-accordion"
import { Minus, Plus } from "lucide-react"
import { cn as classNames } from "@/lib/utils"

type AccordionContextType = {
	size?: "sm" | "lg"
	variant?: "open" | "closed"
}
type AccordionProps = React.ComponentProps<typeof AccordionPrimitive.Root> & AccordionContextType
type AccordionItemProps = React.ComponentProps<typeof AccordionPrimitive.Item> & {
	className?: string
}
type AccordionTriggerProps = React.ComponentProps<typeof AccordionPrimitive.Trigger> & {
	className?: string
}
type AccordionContentProps = React.ComponentProps<typeof AccordionPrimitive.Content> & {
	className?: string
}

const AccordionContext = React.createContext<AccordionContextType | null>(null)

function useAccordion() {
	const context = React.use(AccordionContext)

	if (!context) {
		throw new Error("useAccordion must be used within a <Accordion />")
	}

	return context
}

function Accordion({ size = "lg", variant = "open", className, children, ...props }: AccordionProps) {
	return (
		<AccordionContext.Provider value={{ size: size, variant: variant }}>
			<AccordionPrimitive.Root data-slot="accordion" className={classNames("w-full", size === "sm" ? "text-sm" : "text-base", className)} {...props}>
				{children}
			</AccordionPrimitive.Root>
		</AccordionContext.Provider>
	)
}

Accordion.displayName = "Accordion"

function AccordionItem({ children, className, ...props }: AccordionItemProps) {
	const { variant } = useAccordion()
	const borderClass = variant === "closed" ? "mb-2 rounded-md border last:mb-0" : "border-b last:border-b-0"

	return (
		<AccordionPrimitive.Item data-slot="accordion-item" className={classNames("overflow-hidden", borderClass, className)} {...props}>
			{children}
		</AccordionPrimitive.Item>
	)
}

AccordionItem.displayName = "AccordionItem"

function AccordionTrigger({ children, className, ...props }: AccordionTriggerProps) {
	const { size, variant } = useAccordion()
	const paddingClass = variant === "closed" ? (size === "sm" ? "p-4 " : "p-5 ") : size === "sm" ? "py-4 " : "py-5"

	return (
		<AccordionPrimitive.Header className="flex">
			<AccordionPrimitive.Trigger
				data-slot="accordion-trigger"
				className={classNames(
					"group bg-bg1 text-fg1 flex flex-1 cursor-pointer items-center justify-between text-left font-medium outline-hidden",
					paddingClass,
					className
				)}
				{...props}>
				{children}
				<Plus className="text-fg2 size-5 shrink-0 group-data-[state=open]:hidden" aria-hidden />
				<Minus className="text-fg2 size-5 shrink-0 group-data-[state=closed]:hidden" aria-hidden />
			</AccordionPrimitive.Trigger>
		</AccordionPrimitive.Header>
	)
}

AccordionTrigger.displayName = "AccordionTrigger"

function AccordionContent({ children, className, ...props }: AccordionContentProps) {
	const { size, variant } = useAccordion()
	const paddingClass = variant === "closed" ? (size === "sm" ? "p-4 pt-0" : "p-5 pt-0") : size === "sm" ? "pb-4" : "pb-5"

	return (
		<AccordionPrimitive.Content
			data-slot="accordion-content"
			className={classNames(
				"text-fg2 data-[state=closed]:animate-accordion-up data-[state=open]:animate-accordion-down overflow-hidden transition-all",
				className
			)}
			{...props}>
			<div className={paddingClass}>{children}</div>
		</AccordionPrimitive.Content>
	)
}

AccordionContent.displayName = "AccordionContent"

export { Accordion, AccordionContent, AccordionItem, AccordionTrigger }

import React from "react"
import { type VariantProps, cva } from "class-variance-authority"
import { CircleCheck, Info, Star, Trash2, TriangleAlert } from "lucide-react"
import { cn } from "@/lib/utils"

type AlertProps = React.HTMLAttributes<HTMLDivElement> &
	VariantProps<typeof alertVariants> & {
		title: string
		message: string
	}

const alertVariants = cva("w-full rounded-md p-4 flex gap-3", {
	variants: {
		type: {
			neutral: "border bg-bg2",
			info: "border-information bg-information/10 text-information",
			success: "border-success bg-success/10 text-success",
			danger: "border-error bg-error/10 text-error",
			warning: "border-warning bg-warning/10 text-warning",
		},
		variant: {
			default: "",
			bordered: "border bg-transparent",
		},
	},
	defaultVariants: {
		type: "neutral",
		variant: "default",
	},
	compoundVariants: [
		{
			type: "neutral",
			variant: "bordered",
			className: "border bg-transparent",
		},
	],
})

const icons = {
	neutral: <Star className="h-5 w-5" />,
	info: <Info className="h-5 w-5" />,
	success: <CircleCheck className="h-5 w-5" />,
	danger: <Trash2 className="h-5 w-5" />,
	warning: <TriangleAlert className="h-5 w-5" />,
}

function Alert({ type = "neutral", variant = "default", title, message, className, ...props }: AlertProps) {
	return (
		<section className={cn(alertVariants({ type, variant, className }))} {...props}>
			<div>{icons[type as keyof typeof icons]}</div>
			<div className="flex flex-col gap-0.5">
				<p className="body-sm font-medium">{title}</p>
				<p className={cn("body-sm", type === "neutral" && "text-fg2")}>{message}</p>
			</div>
		</section>
	)
}

export { Alert }

"use client"

import React from "react"
import { type VariantProps, cva } from "class-variance-authority"
import { UserIcon } from "lucide-react"
import { cn } from "@/lib/utils"

type AvatarProps = {
	src?: string
	name: string
	className?: string
	size?: NonNullable<VariantProps<typeof avatarVariants>["size"]>
	variant?: NonNullable<VariantProps<typeof avatarVariants>["variant"]>
	onlineStatus?: NonNullable<VariantProps<typeof onlineIndicatorVariants>["status"]>
}

type AvatarGroupProps = React.HTMLAttributes<HTMLDivElement> & {
	children: React.ReactElement<typeof Avatar> | React.ReactElement<typeof Avatar>[]
	size?: NonNullable<VariantProps<typeof avatarGroupVariants>["size"]>
	max?: number
	className?: string
}

const avatarVariants = cva("flex items-center justify-center shrink-0 overflow-hidden font-semibold text-fg2", {
	variants: {
		size: {
			"20": "size-5 text-[0.5rem]",
			"24": "size-6 text-[0.625rem]",
			"32": "size-8 text-xs",
			"36": "size-9 text-xs",
			"40": "size-10 text-sm",
			"48": "size-12 text-base",
			"64": "size-16 text-xl",
			"80": "size-20 text-2xl",
			"120": "size-30 text-[2rem]",
		},
		variant: {
			circle: "rounded-full",
			square: "",
		},
	},
	compoundVariants: [
		{ size: "20", variant: "square", className: "rounded-md" },
		{ size: "24", variant: "square", className: "rounded-md" },
		{ size: "32", variant: "square", className: "rounded-lg" },
		{ size: "36", variant: "square", className: "rounded-lg" },
		{ size: "40", variant: "square", className: "rounded-xl" },
		{ size: "48", variant: "square", className: "rounded-xl" },
		{ size: "64", variant: "square", className: "rounded-2xl" },
		{ size: "80", variant: "square", className: "rounded-[1.25rem]" },
		{ size: "120", variant: "square", className: "rounded-3xl" },
	],
	defaultVariants: {
		size: "40",
		variant: "circle",
	},
})

const onlineIndicatorVariants = cva("absolute z-20 border-bg1 box-content rounded-full", {
	variants: {
		size: {
			"20": "size-1 border-2 -bottom-0.5 -right-0.5",
			"24": "size-1.25 border-2 -bottom-0.5 -right-0.5",
			"32": "size-2 border-4 -bottom-1 -right-1",
			"36": "size-2 border-4 -bottom-1 -right-1",
			"40": "size-2.5 border-4 -bottom-1 -right-1",
			"48": "size-2.5 border-4 -bottom-1 -right-1",
			"64": "size-3.5 border-6 -bottom-1.5 -right-1.5",
			"80": "size-4 border-8 -bottom-2 -right-2",
			"120": "size-6 border-12 -bottom-3 -right-3",
		},
		status: {
			true: "bg-success",
			false: "bg-bg4",
		},
	},
	defaultVariants: {
		size: "40",
		status: false,
	},
})

const avatarGroupVariants = cva("flex items-center", {
	variants: {
		size: {
			"20": "-space-x-1.5",
			"24": "-space-x-2",
			"32": "-space-x-2.5",
		},
	},
	defaultVariants: {
		size: "32",
	},
})

function getInitials(name: string) {
	if (!name) return ""
	if (name.startsWith("+")) return name
	const initials = name.split(" ").map((word) => word.charAt(0).toUpperCase())
	return initials.slice(0, 2).join("")
}

function Avatar({ src, name, className, size = "40", variant = "circle", onlineStatus }: AvatarProps) {
	const [imageStatus, setImageStatus] = React.useState<"loading" | "loaded" | "error">("loading")

	React.useEffect(() => {
		if (!src) {
			setImageStatus("error")
			return
		}

		const img = new Image()
		img.src = src
		img.onload = () => setImageStatus("loaded")
		img.onerror = () => setImageStatus("error")

		return () => {
			img.onload = null
			img.onerror = null
		}
	}, [src])

	return (
		<div data-slot="avatar" className="relative">
			<div className={cn(avatarVariants({ size, variant }), "bg-bg3", className)}>
				{src && imageStatus === "loaded" && <img src={src} alt={name} className="size-full object-cover" />}

				{imageStatus !== "loaded" && (
					<span className="flex size-full items-center justify-center">
						{name ? (
							// Show initials if name is provided
							getInitials(name)
						) : (
							// Show fallback icon if no name
							<UserIcon className={`size-${size}`} />
						)}
					</span>
				)}
			</div>

			{/* Only render indicator if onlineStatus is explicitly set */}
			{onlineStatus !== undefined && (
				<span
					className={onlineIndicatorVariants({
						size,
						status: onlineStatus,
					})}
				/>
			)}
		</div>
	)
}

Avatar.displayName = "Avatar"

function AvatarGroup({ children, size = "24", max = 4, className, ...props }: AvatarGroupProps) {
	const getBorderStyles = (size: string): string | null => {
		if (size === "20") return "border-2 border-bg1"
		if (size === "24") return "border-2 border-bg1"
		if (size === "32") return "border-4 border-bg1"
		return null
	}

	const avatarChildren = React.Children.toArray(children)

	// Calculate how many avatars to show and if we need a count
	const visibleAvatars = avatarChildren.slice(0, max)
	const remainingCount = Math.max(0, avatarChildren.length - max)
	const visibleCount = remainingCount > 99 ? "+99" : `+${remainingCount}`

	return (
		<div data-slot="avatar-group" className={cn(avatarGroupVariants({ size }), className)} {...props}>
			{visibleAvatars.map((child, index) => (
				<div key={index}>
					{React.cloneElement(child as React.ReactElement<AvatarProps>, {
						size,
						className: cn(getBorderStyles(size), "box-content", (child as React.ReactElement<AvatarProps>).props.className),
					})}
				</div>
			))}

			{/* Show remaining count if any */}
			{remainingCount > 0 && <Avatar name={visibleCount} size={size} className={cn(getBorderStyles(size), "bg-primary box-content text-white")} />}
		</div>
	)
}

AvatarGroup.displayName = "AvatarGroup"

export { Avatar, AvatarGroup }

"use client"

import { useState } from "react"
import { type VariantProps, cva } from "class-variance-authority"
import { X } from "lucide-react"
import { cn } from "@/lib/utils"

type BadgeProps = React.HTMLAttributes<HTMLDivElement> &
	Omit<VariantProps<typeof badgeVariants>, "size"> & {
		closable?: boolean
		size?: BadgeSize
	}
type BadgeSize = "20" | "24" | "28" | "32"

const badgeVariants = cva("inline-flex items-center font-medium box-border", {
	variants: {
		variant: {
			outline: "border",
			strong: "bg-primary text-white font-semibold",
		},
		size: {
			"20": "h-5 px-1.5 body-xs",
			"24": "h-6 px-2 body-sm",
			"28": "h-7 px-2.5 body-sm",
			"32": "h-8 px-3 body-sm",
		},
		rounded: {
			true: "rounded-full",
			false: "rounded-md",
		},
	},
	defaultVariants: {
		variant: "outline",
		size: "24",
		rounded: false,
	},
})

const iconSizeMap: Record<BadgeSize, string> = {
	"20": "size-3",
	"24": "size-3",
	"28": "size-4",
	"32": "size-4",
}

function Badge({ variant = "outline", size = "24", rounded = false, closable = false, className, children, ...props }: BadgeProps) {
	const [showBadge, setShowBadge] = useState(true)

	return (
		showBadge && (
			<div className={cn(badgeVariants({ variant, size, rounded }), className)} {...props}>
				<div className="flex items-center gap-1">
					{Array.isArray(children)
						? children.map((child, index) =>
								typeof child === "object" && "type" in child && (child.type === "svg" || typeof child.type === "function") ? (
									<span key={index} className="flex items-center">
										{child}
									</span>
								) : (
									child
								)
							)
						: children}
					{closable && (
						<X
							onClick={() => setShowBadge(false)}
							className={cn(variant === "outline" ? "text-fg2" : "text-white", iconSizeMap[size], "cursor-pointer font-extrabold")}
						/>
					)}
				</div>
			</div>
		)
	)
}

export { Badge }

"use client"

import { HTMLAttributes, ReactNode, useState } from "react"
import { VariantProps, cva } from "class-variance-authority"
import { X } from "lucide-react"

type BannerProps = HTMLAttributes<HTMLDivElement> &
	VariantProps<typeof bannerVariants> & {
		children: ReactNode
		variant?: "dark" | "transparent" | "soft"
		closable?: boolean
	}

const bannerVariants = cva("py-2 px-4 flex items-center justify-center gap-2.5 relative body-sm w-full", {
	variants: {
		variant: {
			dark: "bg-black text-white",
			transparent: "bg-transparent border-b",
			soft: "bg-bg4",
		},
	},
	defaultVariants: {
		variant: "dark",
	},
})

function Banner({ children, variant = "dark", closable, ...props }: BannerProps) {
	const [showBanner, setShowBanner] = useState(true)

	return (
		showBanner && (
			<div {...props} className={bannerVariants({ variant })}>
				{children}
				{closable && <X size={16} onClick={() => setShowBanner(false)} className="stroke-fg3 absolute right-4 cursor-pointer" />}
			</div>
		)
	)
}
export { Banner }

"use client"

import React, { useEffect, useState } from "react"
import { ChevronRight, Ellipsis, Slash } from "lucide-react"
import { cn } from "@/lib/utils"
import { Badge } from "./badge"
import { Dropdown, DropdownContent, DropdownGroup, DropdownItem, DropdownTrigger } from "./dropdown"

type BaseProps = React.HTMLAttributes<HTMLElement> & {
	className?: string
	children?: React.ReactNode
}

type BreadcrumbProps = BaseProps & {
	separatorType?: "default" | "slash"
	maxItems?: number
}

type BreadcrumbItemProps = BaseProps & {
	href?: string
	isCurrent?: boolean
	showSeparator?: boolean
	separatorType?: "default" | "slash"
}

function Breadcrumb({ children, className = "", separatorType = "default", maxItems: maxItemsProp = 5, ...props }: BreadcrumbProps) {
	const [maxItems, setMaxItems] = useState(maxItemsProp)

	useEffect(() => {
		const handleResize = () => {
			setMaxItems(window.innerWidth <= 640 ? 2 : window.innerWidth <= 768 ? 3 : window.innerWidth <= 1024 ? 4 : maxItemsProp)
		}

		handleResize()
		window.addEventListener("resize", handleResize)
		return () => window.removeEventListener("resize", handleResize)
	}, [maxItemsProp])

	const childArray = React.Children.toArray(children)
	const shouldShowEllipsis = childArray.length > maxItems
	const visibleItems = shouldShowEllipsis ? [childArray[0], ...childArray.slice(-maxItems + 1)] : childArray
	const invisibleItems = shouldShowEllipsis ? childArray.slice(1, -maxItems + 1) : []

	return (
		<nav className={cn("flex items-center", className)} {...props}>
			<ol className="flex items-center justify-center gap-1.5">
				{visibleItems.map((child, index, array) => {
					if (!React.isValidElement<BreadcrumbItemProps>(child)) return child

					const isLast = index === array.length - 1
					const showEllipsis = shouldShowEllipsis && index === 0

					return (
						<React.Fragment key={child.key ?? index}>
							{React.cloneElement(child, {
								...child.props,
								showSeparator: !isLast || showEllipsis,
								separatorType,
							})}
							{showEllipsis && (
								<>
									<BreadcrumbItem className="cursor-default hover:no-underline">
										<Dropdown>
											<DropdownTrigger asChild>
												<Badge className="cursor-pointer" size="20" rounded>
													<Ellipsis size={16} />
												</Badge>
											</DropdownTrigger>
											<DropdownContent>
												<DropdownGroup>
													{invisibleItems.map((hiddenChild, hiddenIndex) =>
														React.isValidElement<BreadcrumbItemProps>(hiddenChild) ? (
															<DropdownItem key={hiddenChild.key ?? hiddenIndex}>
																<a className="flex items-center justify-start gap-0.5" href={hiddenChild.props.href}>
																	{hiddenChild.props.children}
																</a>
															</DropdownItem>
														) : null
													)}
												</DropdownGroup>
											</DropdownContent>
										</Dropdown>
									</BreadcrumbItem>
									{separatorType === "slash" ? <Slash size={14} className="stroke-fg3" /> : <ChevronRight size={14} className="stroke-fg3" />}
								</>
							)}
						</React.Fragment>
					)
				})}
			</ol>
		</nav>
	)
}
Breadcrumb.displayName = "Breadcrumb"

function BreadcrumbItem({
	children,
	href,
	isCurrent = false,
	className = "",
	showSeparator = false,
	separatorType = "default",
	...props
}: BreadcrumbItemProps) {
	const Comp = href ? "a" : "span"
	const SeparatorIcon = separatorType === "slash" ? Slash : ChevronRight

	return (
		<>
			<li className="flex items-center justify-center" {...props}>
				<Comp
					href={href}
					className={cn(
						"body-sm flex items-center gap-1 font-medium transition-colors",
						isCurrent ? "font-medium" : "text-fg2",
						href && "hover:underline",
						"[&>svg]:h-full [&>svg]:max-h-5 [&>svg]:w-auto",
						className
					)}>
					{children}
				</Comp>
			</li>
			{showSeparator && <SeparatorIcon size={14} className="stroke-fg3" />}
		</>
	)
}

BreadcrumbItem.displayName = "BreadcrumbItem"

export { Breadcrumb, BreadcrumbItem }

import React from "react"
import { type VariantProps, cva } from "class-variance-authority"
import { cn } from "@/lib/utils"

type ButtonProps = VariantProps<typeof buttonVariants> &
	React.ButtonHTMLAttributes<HTMLButtonElement> & {
		className?: string
		children: React.ReactNode
		isIcon?: boolean
	}

type ButtonGroupProps = React.HTMLAttributes<HTMLDivElement> & {
	children: React.ReactNode
	variant?: ButtonProps["variant"]
	size?: ButtonProps["size"]
	rounded?: ButtonProps["rounded"]
}

const buttonVariants = cva("inline-flex items-center justify-center box-border", {
	variants: {
		variant: {
			strong: "bg-primary font-semibold text-white hover:bg-primary-500 active:bg-primary-700",
			soft: "bg-primary/10 font-medium text-primary hover:bg-primary/15 active:bg-primary/20",
			outline: "bg-bg1 font-medium border border-primary text-primary hover:bg-primary/5 active:bg-primary/10",
			ghost: "bg-transparent text-primary font-medium hover:bg-primary/10 active:bg-primary/20",
			"neutral-soft": "bg-bg2 font-medium hover:bg-bg3 active:bg-bg4",
			"neutral-outline": "bg-bg1 font-medium border drop-shadow-xs hover:border-stroke-decorative active:bg-bg2 active:border-stroke-decorative",
		},
		rounded: {
			square: "rounded-xs",
			rounded: "rounded-md",
			full: "rounded-full",
		},
		size: {
			"32": "[&>svg]:size-5 body-sm", // 32px (formerly xs)
			"36": "[&>svg]:size-5 body-sm", // 36px (formerly sm)
			"40": "[&>svg]:size-5 body-sm", // 40px (formerly base)
			"44": "[&>svg]:size-6 body-base", // 44px (formerly lg)
			"48": "[&>svg]:size-6 body-base", // 48px (formerly xl)
			"56": "[&>svg]:size-6 body-base", // 56px (formerly 2xl)
		},
		isIcon: {
			true: "",
			false: "",
		},
	},
	defaultVariants: {
		variant: "strong",
		size: "40",
		rounded: "rounded",
		isIcon: false,
	},
	compoundVariants: [
		{ isIcon: false, size: "32", className: "gap-1.5 h-8 px-2.5" }, // 32px
		{ isIcon: false, size: "36", className: "gap-1.5 h-9 px-3" }, // 36px
		{ isIcon: false, size: "40", className: "gap-1.5 h-10 px-3.5" }, // 40px
		{ isIcon: false, size: "44", className: "gap-2 h-11 px-4" }, // 44px
		{ isIcon: false, size: "48", className: "gap-2 h-12 px-4.5" }, // 48px
		{ isIcon: false, size: "56", className: "gap-2 h-14 px-5" }, // 56px

		{ isIcon: true, size: "32", className: "px-1.5 h-8 gap-1.5" }, // 32px
		{ isIcon: true, size: "36", className: "px-2 h-9 gap-1.5" }, // 36px
		{ isIcon: true, size: "40", className: "px-2.5 h-10 gap-1.5" }, // 40px
		{ isIcon: true, size: "44", className: "px-2.5 h-11 gap-2" }, // 44px
		{ isIcon: true, size: "48", className: "px-3 h-12 gap-2" }, // 48px
		{ isIcon: true, size: "56", className: "px-4 h-14 gap-2" }, // 56px
	],
})

function Button({ variant = "strong", size = "40", rounded = "rounded", isIcon = false, className, children, ...props }: ButtonProps) {
	return (
		<button className={cn(buttonVariants({ variant, size, rounded, isIcon }), className)} {...props}>
			{children}
		</button>
	)
}
Button.displayName = "Button"

function ButtonGroup({ className, children, variant = "outline", size = "40", rounded = "rounded", ...props }: ButtonGroupProps) {
	const modifiedChildren = React.Children.map(children, (child, index) => {
		if (React.isValidElement(child)) {
			const isFirst = index === 0
			const isLast = index === React.Children.count(children) - 1
			const borderRightClass = variant === "outline" || variant === "neutral-outline" ? "border-r" : ""

			return React.cloneElement(child as React.ReactElement<ButtonProps>, {
				variant,
				size,
				className: cn(
					child.props.className,
					"relative focus:z-10",
					borderRightClass,
					"rounded-none",
					isFirst && rounded === "rounded" && "rounded-l-md",
					isFirst && rounded === "square" && "rounded-l-xs",
					isFirst && rounded === "full" && "rounded-l-full",
					isLast && rounded === "rounded" && "rounded-r-md",
					isLast && rounded === "square" && "rounded-r-xs",
					isLast && rounded === "full" && "rounded-r-full",
					!isFirst && "-ml-px"
				),
			})
		}
		return child
	})

	return (
		<div className={cn("inline-flex", className)} role="group" {...props}>
			{modifiedChildren}
		</div>
	)
}
ButtonGroup.displayName = "ButtonGroup"

