// Function to get the decimal separator based on the locale
function getDecimalSeparator(locale: Intl.LocalesArgument) {
	const testNum = 1.1
	return new Intl.NumberFormat(locale, { style: "decimal" }).format(testNum).charAt(1)
}

// const getThousandsSeparator = (locale: Intl.LocalesArgument) => {
// 	const testNum = 1111;
// 	return new Intl.NumberFormat(locale, { style: "decimal" }).format(testNum).charAt(1);
// };

// function removeByIndex(str: string, index: number) {
// 	return str.slice(0, index) + str.slice(index + 1);
// }

// Type definition for CurrencyInput props, extending standard input attributes
export type CurrencyInputProps = Omit<React.InputHTMLAttributes<HTMLInputElement>, "type" | "size"> & {
	currencyCode?: ListedCurrencyCodes
	onNumericValueChange?: (value: number) => void
	maxLength?: number
	allowDecimals?: boolean
	maxFractionDigits?: number
	minFractionDigits?: number
	locale?: Intl.LocalesArgument
}

// CurrencyInput component that displays a currency input field
function CurrencyInput({
	className,
	currencyCode = "USD",
	onValueChange,
	onNumericValueChange,
	value,
	maxLength = 17, // JS can't handle numbers greater than 17 digits
	allowDecimals = true,
	maxFractionDigits = 20,
	minFractionDigits,
	locale = "en-US",
	size = defaultInputSize,
	rounded = defaultInputRadius,
	defaultValue = "",
	ref,
	...props
}: CurrencyInputProps & InputProps) {
	const isControlled = value !== undefined
	const [internalValue, setInternalValue] = React.useState<string>(defaultValue.toString())
	const currentValue = isControlled ? value.toString() : internalValue
	const decimalSeparator = getDecimalSeparator(locale)
	// const thousandsSeparator = getThousandsSeparator(locale);

	const inputRef = React.useRef<HTMLInputElement>(null)
	React.useImperativeHandle(ref, () => inputRef.current!, [])
	const prevValueT = React.useRef<string>(currentValue)
	const prevCursorT = React.useRef<number>(inputRef.current?.selectionStart || 0)
	// Function to remove non-numeric characters from the formatted value
	const unformatValue = (formatted: string): string => {
		return formatted.replace(new RegExp(`[^\\d${decimalSeparator}]`, "g"), "")
	}
	// Function to format the numeric value for display based on locale
	function formatValue(value: string): string {
		/* 
			Change the value into en-US locale because
			parseFloat only handles en-US locale numbers
			*/
		const changedLocale = value.replace(decimalSeparator, ".")
		const parsed = parseFloat(changedLocale)
		if (isNaN(parsed)) return ""

		return new Intl.NumberFormat(locale, {
			style: "decimal",
			maximumFractionDigits: maxFractionDigits,
			minimumFractionDigits: minFractionDigits,
		}).format(parsed)
	}
	// Proxy function to handle value changes
	function onValueChangeProxy(changedValue: string) {
		if (changedValue == "") {
			onNumericValueChange?.(0)
			onValueChange?.("")
			if (!isControlled) setInternalValue("")
			return
		}

		// Change the formatted value into numeric value first
		const numericValue = unformatValue(changedValue)

		// if (numericValue == unformatValue(prevValueT.current))
		// 	numericValue = unformatValue(removeByIndex(prevValueT.current, prevCursorT.current - 2));

		// Check if the value is a valid number with or without decimals
		const regex = new RegExp(allowDecimals ? `^\\d*\\${decimalSeparator}?\\d{0,${maxFractionDigits}}$` : "^\\d*$")
		const isValidNumber = regex.test(numericValue)
		if (!isValidNumber) {
			return
		}
		// Check if the length of the number is greater than the maxLength
		if (maxLength && changedValue.replace(/[^\d]/g, "").length > maxLength) return

		const parsed = parseFloat(numericValue) || 0
		onNumericValueChange?.(parsed)

		let formatted = formatValue(numericValue)

		// Retain the decimalSeparator while typing
		if (numericValue.charAt(numericValue.length - 1) === decimalSeparator) {
			formatted += decimalSeparator
		}
		onValueChange?.(formatted)
		if (!isControlled) setInternalValue(formatted)

		requestAnimationFrame(() => {
			if (!inputRef.current) return

			const cursorOffset = formatted.length - prevValueT.current.length
			const newCursor = prevCursorT.current + cursorOffset
			inputRef.current.setSelectionRange(newCursor, newCursor)

			prevValueT.current = formatted
			prevCursorT.current = newCursor
		})
	}

	// Function to update cursor position on user interaction
	function updateCursorPosition() {
		if (inputRef.current) {
			prevCursorT.current = inputRef.current.selectionStart || 0
		}
	}
	// Handle keyboard events to manage cursor position during deletion
	function handleDelete(e: React.KeyboardEvent<HTMLInputElement>) {
		if (inputRef.current) {
			if (e.key == "Delete") prevCursorT.current = (inputRef.current.selectionStart || 0) + 1
		}
	}

	return (
		<Input
			ref={inputRef}
			prefixIcon={<span className="text-fg3">{CURRENCY_CODES.find((currency) => currency.currencyCode === currencyCode)?.currencySymbol}</span>}
			suffixIcon={<span>{currencyCode}</span>}
			className={cn("h-full", className)}
			size={size}
			type="text"
			rounded={rounded}
			onValueChange={onValueChangeProxy}
			value={currentValue}
			onClick={updateCursorPosition}
			onKeyUp={updateCursorPosition}
			onMouseUp={updateCursorPosition}
			onKeyDown={handleDelete}
			{...props}
		/>
	)
}
