				inset && "pl-9",
				className
			)}
			asChild={asChild}
			onSelect={handleSelect}
			{...props}>
			{asChild ? (
				children
			) : (
				<>
					{icon && <span>{icon}</span>}
					<span className="flex w-full gap-2 truncate font-normal">{children}</span>
					{shortcut && (
						<label
							className={cn(
								"border-stroke text-fg2 ml-auto flex h-5 items-center justify-center rounded-sm border px-1.5 py-0 text-xs/4.5 drop-shadow-xs"
							)}>
							{shortcut}
						</label>
					)}
					{isSelectable && <span className="flex h-2.5 w-3.5 items-center">{isSelected && <Check className="text-fg1" size={20} />}</span>}
				</>
			)}
		</DropdownMenuPrimitive.Item>
	)
}
DropdownItem.displayName = "DropdownItem"

// Type definition for DropdownGroup props
type DropdownGroupProps = {
	selectionMode?: "single" | "multiple"
	selectedValues?: string[]
	onSelectedChange?: (selectedValues: string[]) => void
	minSelectionCount?: number
}

const DropdownCtx = React.createContext<DropdownGroupProps>({ selectionMode: undefined })
// DropdownGroup component definition
function DropdownGroup({
	children,
	title,
	selectionMode,
	selectedValues = [],
	onSelectedChange,
	className,
	minSelectionCount = 0,
	...props
}: DropdownMenuGroupProps & React.RefAttributes<HTMLDivElement> & DropdownGroupProps) {
	if (minSelectionCount < 0) throw new Error("minSelectionCount cannot be negative")

	React.useEffect(
		function () {
			if (selectedValues.length < minSelectionCount) console.warn("minSelectionCount is greater than the number of selected keys")
		},
		[selectedValues, minSelectionCount]
	)

	const contextValue = React.useMemo(
		function () {
			return { selectionMode, selectedValues, onSelectedChange, minSelectionCount }
		},
		[selectionMode, selectedValues, onSelectedChange, minSelectionCount]
	)
	return (
		<>
			<DropdownCtx.Provider value={contextValue}>
				<DropdownMenuPrimitive.Group className={cn(className, "bg-bg1 z-50 flex flex-col items-stretch justify-start px-0 py-0")} {...props}>
					{title && <label className="text-fg3 flex h-7 items-center px-2 py-2.5 text-xs/4.5 font-medium uppercase">{title}</label>}
					{children}
				</DropdownMenuPrimitive.Group>
			</DropdownCtx.Provider>
		</>
	)
}

DropdownGroup.displayName = "DropdownGroup"

// DropdownSub component definition
function DropdownSub({ children, ...props }: React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.Sub>) {
