import React from "react"
import { cn } from "@/lib/utils"

/* 
	These component is used underneath
	by other components like Text, Email, Password, etc.
*/
type InputInnerProps = React.InputHTMLAttributes<HTMLInputElement> & {
	onValueChange?: (value: string) => void
	ref?: React.Ref<HTMLInputElement>
}
// InputInner component definition
function InputInner({ id, className, disabled, type = "text", value, onValueChange, defaultValue = "", ...props }: InputInnerProps) {
	const isControlled = value !== undefined
	const [val, setVal] = React.useState<string>(defaultValue.toString())

	const currentValue = isControlled ? value : val
	// Handle value change for the input
	function handleChange(changedValue: string) {
		if (isControlled) {
			onValueChange?.(changedValue)
		} else {
			setVal(changedValue)
		}
	}

	return (
		<input
			id={id}
			className={cn(
				"text-fg-1 placeholder-fg3 h-fit w-full border border-none bg-transparent p-0 outline-hidden select-none placeholder:text-sm placeholder:font-normal focus:ring-0",
				{
					"text-fg3 cursor-not-allowed": disabled,
				},
				className
			)}
			type={type}
			disabled={disabled}
			value={currentValue}
			onChange={(e) => handleChange(e.target.value)}
			{...props}
		/>
	)
}
InputInner.displayName = "Input"
// Type definition for Label props
type LabelProps = React.LabelHTMLAttributes<HTMLLabelElement> & {
	disabled?: boolean
