import React from "react"
import { Time } from "@internationalized/date"
import { cn } from "@/lib/utils"
import { Select, SelectItem, SelectProps } from "./select"

export type TimePickerProps = Pick<
	SelectProps,
	"className" | "classNames" | "defaultSelected" | "label" | "placeholder" | "rounded" | "size" | "renderTrigger" | "disabled"
> & {
	interval?: number
	value?: Time | null
	onValueChange?: (time: Time | null) => void
	is24Hour?: boolean
	minTime?: string
	maxTime?: string
	defaultValue?: Time
	allowEmptySelection?: boolean
}

/**
 * Converts a Dayjs object to a string in "HH:mm" format.
 * @param time - The Dayjs object to format.
 * @returns The formatted time string.
 */
function serializeTime(time: Time) {
	const hour = String(time.hour).padStart(2, "0")
	const minute = String(time.minute).padStart(2, "0")
	return `${hour}:${minute}`
}

/**
 * Converts a string in "HH:mm" format to a Time object.
 * @param timeString - The time string to parse.
 * @returns A Time object representing the given time.
 */
function deserializeTime(timeString: string) {
	const [hour, minute] = timeString.split(":").map(Number)
	return new Time(hour, minute)
}

function TimePicker({
	interval = 15,
	onValueChange,
	is24Hour = false,
	minTime = "00:00",
	maxTime = "23:59",
	defaultValue,
	value = null,
	allowEmptySelection = true,
	classNames,
	...props
}: TimePickerProps) {
	const isControlled = value !== null

	/* Store the time as a serialized string ("HH:mm") to simplify comparisons and render */
	const [internalValue, setInternalValue] = React.useState<string[]>(defaultValue ? [serializeTime(defaultValue)] : [])

	const currentValue = isControlled ? serializeTime(value) : internalValue[0]

	/**
	 * Generates an array of Dayjs objects representing selectable time options.
	 *
	 * The function computes times starting from minTime until maxTime using the provided interval.
	 * We choose this approach to support various ranges and intervals without hardcoding values.
	 *
	 * @returns An array of Dayjs objects for each selectable time.
	 */
	function generateTimeOptions() {
		const times: Time[] = []
		const [minHour, minMinute] = minTime.split(":").map(Number)
		const [maxHour, maxMinute] = maxTime.split(":").map(Number)

		let currentHour = minHour
		let currentMinute = minMinute

		while (currentHour < maxHour || (currentHour === maxHour && currentMinute <= maxMinute)) {
			const time = new Time(currentHour, currentMinute)
			times.push(time)

			currentMinute += interval
			if (currentMinute >= 60) {
				currentHour += Math.floor(currentMinute / 60)
				currentMinute %= 60
			}
		}

		return times
	}

	const timeOptions = generateTimeOptions()
	/**
	 * Handles value changes when a user selects a time.
	 * Updates the internal state and calls the onValueChange callback.
	 * @param value - The selected time as a string.
	 */
	function handleChange(value: string | undefined) {
		if (!value) {
			onValueChange?.(null)
			setInternalValue([])
		} else {
			onValueChange?.(deserializeTime(value))
			setInternalValue([value])
		}
	}
	// Formats a Time object into a human-readable string based on 12-hour or 24-hour format.
	function formatTime(time: Time) {
		let hour = time.hour
		const minute = String(time.minute).padStart(2, "0")
		if (!is24Hour) {
			const period = hour >= 12 ? "pm" : "am"
			hour = hour % 12
			hour = hour === 0 ? 12 : hour // 12 am/pm handling
			return `${String(hour).padStart(2, "0")}:${minute} ${period}`
		} else {
			return `${String(hour).padStart(2, "0")}:${minute}`
		}
	}

	return (
		<Select
			selectedValues={[currentValue]}
			onSelectedChange={function (values) {
				handleChange(values[0])
			}}
			classNames={{ content: cn("h-80"), ...classNames }}
			minSelectionCount={allowEmptySelection ? 0 : 1}
			{...props}>
			{timeOptions.map((time, index) => {
				const formatted = formatTime(time)
				return (
					<SelectItem key={index} value={serializeTime(time)}>
						{formatted}
					</SelectItem>
				)
			})}
		</Select>
	)
}

export default TimePicker

import React, { MutableRefObject, ReactElement, useCallback, useEffect, useRef, useState } from "react"
import { cva } from "class-variance-authority"
import ReactDOM from "react-dom"

type TooltipProps = {
	content: string
	position?: "top" | "bottom" | "left" | "right"
	children: ReactElement
	variant?: "default" | "arrow"
}

function Tooltip({ content, position = "top", children, variant = "default" }: TooltipProps) {
	const [showTooltip, setShowTooltip] = useState(false)
	const [coords, setCoords] = useState<{ top: number; left: number }>({ top: 0, left: 0 })
	const tooltipRef = useRef<HTMLDivElement | null>(null)
	const childRef = useRef<HTMLElement | null>(null)
	const hoverStartRef = useRef<number>(0)
	const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null)
	const observerRef = useRef<MutationObserver | null>(null)

	// Updates the tooltip position based on the target element's position
	const updateTooltipPosition = useCallback(
		function () {
			if (childRef.current && tooltipRef.current) {
				const childRect = childRef.current.getBoundingClientRect()
				const tooltipRect = tooltipRef.current.getBoundingClientRect()

				let top = childRect.top - tooltipRect.height - 6
				let left = childRect.left + childRect.width / 2 - tooltipRect.width / 2

				if (position === "bottom") {
					top = childRect.bottom + 6
				} else if (position === "left") {
					top = childRect.top + childRect.height / 2 - tooltipRect.height / 2
					left = childRect.left - tooltipRect.width - 6
				} else if (position === "right") {
					top = childRect.top + childRect.height / 2 - tooltipRect.height / 2
					left = childRect.right + 6
				}
				setCoords(function (prevCoords) {
					// Only update state if the position actually changed
					if (prevCoords.top !== top || prevCoords.left !== left) {
						return { top, left }
					}
					return prevCoords
				})
			}
		},
		[position]
	)

	// Handles mouse enter event, 700ms delays tooltip appearance
	function handleMouseEnter() {
		hoverStartRef.current = Date.now()
		if (timeoutRef.current) clearTimeout(timeoutRef.current)

		timeoutRef.current = setTimeout(function () {
			if (Date.now() - hoverStartRef.current >= 100) {
				setShowTooltip(true)
			}
		}, 700)
	}
	// Hides tooltip on mouse leave
	function handleMouseLeave() {
		if (timeoutRef.current) clearTimeout(timeoutRef.current)
		setShowTooltip(false)
	}
	// Shows tooltip on focus (for keyboard users)
	function handleFocus() {
		setShowTooltip(true)
		updateTooltipPosition()
	}
	// Hides tooltip when losing focus
	function handleBlur() {
		setShowTooltip(false)
	}
	// Closes tooltip when the Escape key is pressed
	useEffect(
		function () {
			if (!showTooltip) return

			const handleKeyDown = function (event: KeyboardEvent) {
				if (event.key === "Escape") {
					setShowTooltip(false)
				}
			}

			document.addEventListener("keydown", handleKeyDown)

			return function () {
				document.removeEventListener("keydown", handleKeyDown)
			}
		},
		[showTooltip]
	)
	// Recalculates tooltip position when window resizes or scrolls
	useEffect(
		function () {
			if (!showTooltip) return
			updateTooltipPosition()
			function handleUpdate() {
				requestAnimationFrame(updateTooltipPosition)
			}

			window.addEventListener("scroll", handleUpdate, { passive: true })
			window.addEventListener("resize", handleUpdate, { passive: true })

			if (childRef.current) {
				observerRef.current = new MutationObserver(updateTooltipPosition)
				observerRef.current.observe(childRef.current, { attributes: true })
			}

			return function () {
				window.removeEventListener("scroll", handleUpdate)
				window.removeEventListener("resize", handleUpdate)
				if (observerRef.current) observerRef.current.disconnect()
			}
		},
		[showTooltip, updateTooltipPosition]
	)

	// Tooltip position variants
	const getArrowPositionClasses = cva("absolute", {
		variants: {
			position: {
				top: "left-1/2 bottom-[0.2rem] transform -translate-x-1/2 translate-y-full",
				bottom: "left-1/2 top-[0.2rem] transform -translate-x-1/2 -translate-y-full rotate-180",
				left: "top-1/2 right-[0.4rem] -rotate-90 transform -translate-y-1/2 translate-x-full",
				right: "top-1/2 left-[0.35rem] transform -translate-y-1/2 -translate-x-full rotate-90",
			},
		},
		defaultVariants: {
			position: "top",
		},
	})

	const tooltip = showTooltip
		? ReactDOM.createPortal(
				<div
					ref={tooltipRef}
					role="tooltip"
					aria-live="polite"
					className="fixed z-50 flex h-6 w-max items-center justify-center rounded-md bg-black px-2 text-xs font-semibold text-white"
					style={{
						top: `${coords.top}px`,
						left: `${coords.left}px`,
					}}>
					{content}
					{variant === "arrow" && (
						<svg
							xmlns="http://www.w3.org/2000/svg"
							width="15"
							height="8"
							viewBox="0 0 15 8"
							fill="none"
							className={getArrowPositionClasses({ position })}>
							<path
								d="M8.48529 6.58579C7.70424 7.36684 6.43791 7.36684 5.65686 6.58579L7.15256e-06 0.928933L7.07107 0.928932L14.1421 0.928932L8.48529 6.58579Z"
								className="fill-black"
							/>
						</svg>
					)}
				</div>,
				document.body
			)
		: null

	return (
		<>
			{React.cloneElement(children, {
				ref: function (node: HTMLElement | null) {
					childRef.current = node
					if (typeof children.type === "string") return

					const childWithRef = children as React.ReactElement & { ref?: React.Ref<HTMLElement> }
					if (typeof childWithRef.ref === "function") childWithRef.ref(node)
					else if (childWithRef.ref) (childWithRef.ref as MutableRefObject<HTMLElement | null>).current = node
				},
				onMouseEnter: handleMouseEnter,
				onMouseLeave: handleMouseLeave,
				onFocus: handleFocus,
				onBlur: handleBlur,
				"aria-describedby": showTooltip ? "tooltip-content" : undefined,
				tabIndex: 0,
			})}

			{tooltip}
		</>
	)
}

export default Tooltip
